1	use comemo::{Track, Tracked};
2	use ecow::EcoString;
3	use indexmap::IndexMap;
4	use rayon::iter::{IntoParallelRefIterator, ParallelIterator};
5	use rustc_hash::FxBuildHasher;
6	use typst_html::{HtmlElement, HtmlOptions};
7	use typst_layout::PagedDocument;
8	use typst_library::diag::{At, ParallelCollectCombinedResult, SourceResult};
9	use typst_library::foundations::Bytes;
10	use typst_library::introspection::Location;
11	use typst_library::model::{LateLinkResolver, PagedFormat};
12	use typst_pdf::PdfOptions;
13	use typst_render::RenderOptions;
14	use typst_svg::SvgOptions;
15	use typst_syntax::{Span, VirtualPath};
16	
17	use crate::{Bundle, BundleDocument, BundleFile};
18	
19	/// A raw mapping from paths to bytes.
20	pub type VirtualFs = IndexMap<VirtualPath, Bytes, FxBuildHasher>;
21	
22	/// Exports a bundle into a raw virtual file system.
23	#[typst_macros::time(name = "export bundle")]
24	pub fn export(bundle: &Bundle, options: &BundleOptions) -> SourceResult<VirtualFs> {
25	    bundle
26	        .files
27	        .par_iter()
28	        .map(|(path, file)| {
29	            let data = match file {
30	                BundleFile::Document(doc) => {
31	                    let link_resolver =
32	                        LateLinkResolver::new(Some(path), bundle.introspector.as_ref());
33	                    export_document(doc, options, link_resolver.track())
34	                }
35	                BundleFile::Asset(bytes) => Ok(bytes.clone()),
36	            };
37	            data.map(|data| (path.clone(), data))
38	        })
39	        .collect_combined_result()
40	}
41	
42	/// Settings for bundle export.
43	#[derive(Debug, Default)]
44	pub struct BundleOptions {
45	    /// Options for exporting HTML documents.
46	    pub html: HtmlOptions,
47	    /// Options for exporting PDF documents.
48	    pub pdf: PdfOptions,
49	    /// Options for exporting PNG documents.
50	    pub png: RenderOptions,
51	    /// Options for exporting SVG documents.
52	    pub svg: SvgOptions,
53	}
54	
55	/// Exports a single document.
56	fn export_document(
57	    doc: &BundleDocument,
58	    options: &BundleOptions,
59	    link_resolver: Tracked<LateLinkResolver>,
