21	/// An introspector implementation for bundles.
22	#[derive(Clone)]
23	pub struct BundleIntrospector {
24	    /// The paths of and introspectors for all bundle documents. Does not
25	    /// include assets.
26	    children: Vec<(VirtualPath, ChildIntrospector, Location)>,
27	    /// The underlying target-agnostic introspector used for most queries.
28	    /// The positions are off-by-one indices into `children`.
29	    elements: ElementIntrospector<Option<NonZeroUsize>>,
30	    /// Maps from element locations to assigned link anchors. This is used to
31	    /// support intra-doc links. Link anchors are local to the relevant
32	    /// document.
33	    anchors: FxHashMap<Location, EcoString>,
34	}
