36	impl BundleIntrospector {
37	    /// Creates an introspector for a bundle.
38	    #[typst_macros::time(name = "introspect bundle")]
39	    pub(crate) fn new(items: &[Item]) -> BundleIntrospector {
40	        let mut builder = BundleIntrospectorBuilder::default();
41	        for item in items {
42	            builder.discover_item(item);
43	        }
44	        builder.finish()
45	    }
46	
47	    /// Computes all locations that are referenced by intra-doc links of any
48	    /// kind and returns them organized by the document they are in.
49	    pub fn link_targets(&self) -> FxHashMap<&VirtualPath, FxHashSet<Location>> {
50	        let mut map: FxHashMap<&VirtualPath, FxHashSet<Location>> = FxHashMap::default();
51	        for target in LinkElem::find_destinations(self).chain(
52	            self.children
53	                .iter()
54	                .flat_map(|(_, child, _)| child.frame_link_targets())
55	                .copied(),
56	        ) {
57	            let Some(path) = self.path(target) else { continue };
58	            map.entry(path).or_default().insert(target);
59	        }
60	        map
61	    }
62	
63	    /// Enriches an existing introspector with HTML link anchors, which were
64	    /// assigned to the DOM in a post-processing step.
65	    pub fn set_anchors(&mut self, anchors: FxHashMap<Location, EcoString>) {
66	        self.anchors = anchors;
67	    }
