69	    /// Retrieves the child introspector for the given location.
70	    ///
71	    /// Returns `None` if the location is not within a document.
72	    fn child(&self, location: Location) -> Option<&ChildIntrospector> {
73	        let pos = *self.elements.position(location)?;
74	        let index = pos?.get() - 1;
75	        Some(&self.children[index].1)
76	    }
