148	    fn path(&self, location: Location) -> Option<&VirtualPath> {
149	        // Check whether the location is that of an element within one of the
150	        // bundle documents.
151	        let index = *self.elements.position(location)?;
152	        if let Some(index) = index {
153	            return Some(&self.children[index.get() - 1].0);
154	        }
155	
156	        // Check whether the location is that of a document or asset itself.
157	        let content = self.elements.get_by_loc(&location)?;
158	        if let Some(doc) = content.to_packed::<DocumentElem>() {
159	            Some(doc.path.as_ref())
160	        } else if let Some(asset) = content.to_packed::<AssetElem>() {
161	            Some(asset.path.as_ref())
162	        } else {
