183	    /// `FrameItem::Link`.
184	    pub fn frame_link_targets(&self) -> &FxHashSet<Location> {
185	        match self {
186	            Self::Paged(introspector) => introspector.frame_link_targets(),
187	            Self::Html(introspector) => introspector.frame_link_targets(),
188	        }
189	    }
190	}
