193	    type Target = dyn Introspector;
194	
195	    fn deref(&self) -> &Self::Target {
196	        match self {
197	            Self::Paged(introspector) => introspector.as_ref(),
198	            Self::Html(introspector) => introspector.as_ref(),
199	        }
200	    }
201	}
