203	/// An introspector implementation for HTML documents.
204	#[derive(Default)]
205	struct BundleIntrospectorBuilder {
206	    subdocuments: Vec<(VirtualPath, ChildIntrospector, Location)>,
207	    elements: ElementIntrospectorBuilder<Option<NonZeroUsize>>,
208	}
209	
210	impl BundleIntrospectorBuilder {
211	    /// Returns the resulting introspector.
212	    fn finish(self) -> BundleIntrospector {
213	        BundleIntrospector {
214	            children: self.subdocuments,
215	            elements: self.elements.finalize(),
216	            anchors: FxHashMap::default(),
217	        }
218	    }
219	
220	    /// Discovers introspectibles in a bundle item.
221	    fn discover_item(&mut self, item: &Item) {
222	        match item {
223	            Item::Tag(tag) => self.elements.discover_tag(tag, None),
224	            Item::Asset(..) => {}
225	            Item::Document(path, doc, loc) => self.discover_document(path, doc, *loc),
226	        }
227	    }
228	
229	    /// Discovers introspectibles in a bundle document.
230	    fn discover_document(
231	        &mut self,
232	        path: &VirtualPath,
233	        doc: &BundleDocument,
234	        loc: Location,
235	    ) {
236	        let pos = NonZeroUsize::new(1 + self.subdocuments.len());
237	        let subintrospector = match doc {
238	            BundleDocument::Paged(doc, _) => {
239	                self.elements
240	                    .discover_elements(doc.introspector().elements(), |_| pos);
241	                ChildIntrospector::Paged(doc.introspector().clone())
242	            }
243	            BundleDocument::Html(doc) => {
244	                self.elements
245	                    .discover_elements(doc.introspector().elements(), |_| pos);
246	                ChildIntrospector::Html(doc.introspector().clone())
247	            }
248	        };
249	        self.subdocuments.push((path.clone(), subintrospector, loc));
250	    }
251	}
